namespace ghidra.app.plugin.core.compositeeditor;







using docking;
using docking.action;
using docking.widgets.dialogs;
using generic.theme;
using ghidra.util;
using ghidra.util.exception;
using ghidra.util.exception;
using ghidra.util.task;
using ghidra.util.task;

/**
 * Action that allows the user to make multiple duplicates of the selected item
 */
public class DuplicateMultipleAction : CompositeEditorTableAction {

	private static Icon ICON = new GIcon("icon.plugin.composite.editor.duplicate.multiple");
	public static string ACTION_NAME = "Duplicate Multiple of Component";
	private static string GROUP_NAME = COMPONENT_ACTION_GROUP;
	private static string DESCRIPTION = "Duplicate multiple of the selected component";
	private static string[] POPUP_PATH = new string[] { ACTION_NAME };

	private KeyStroke keyStroke = KeyStroke.getKeyStroke(KeyEvent.VK_M, InputEvent.ALT_DOWN_MASK);

	public DuplicateMultipleAction(CompositeEditorProvider<object,object> provider) : base(provider, ACTION_NAME, GROUP_NAME, POPUP_PATH, null, ICON)
    {
		setDescription(DESCRIPTION);
		setKeyBindingData(new KeyBindingData(keyStroke));
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		if (!isEnabledForContext(context)) {
			return;
		}
		int[] indices = model.getSelectedComponentRows();
		if (indices.length != 1) {
			return;
		}

		int row = indices[0];
		int min = 1;
		int max = model.getMaxDuplicates(row);
		if (max == 0) {
			return;
		}

		int initial = model.getLastNumDuplicates();
		NumberInputDialog numberInputDialog =
			new NumberInputDialog("duplicates", ((initial > 0) ? initial : 1), min, max);
		string helpAnchor = provider.getHelpName() + "_" + "Duplicates_NumberInputDialog";
		HelpLocation helpLoc = new HelpLocation(provider.getHelpTopic(), helpAnchor);
		numberInputDialog.setHelpLocation(helpLoc);

		if (numberInputDialog.show()) {
			int count = numberInputDialog.getValue();
			TaskLauncher.launchModal("Duplicating Component",
				monitor => doInsert(row, count, monitor));
		}

		requestTableFocus();
	}

	private void doInsert(int row, int count, TaskMonitor monitor) {
		try {
			model.duplicateMultiple(row, count, monitor);
		}
		catch (CancelledException e) {
			// user cancelled
		}
		catch (UsrException e) {
			model.setStatus(e.getMessage(), true);
		}
		model.fireTableDataChanged();
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		return !hasIncompleteFieldEntry() && model.isDuplicateAllowed();
	}

}
